descriptor.controllerScript:
self.onInit = function () {
  self.cpu_usage = 0;
  self.ram_usage = 0;
  self.flash_usage = 0;
  self.device_temperature = 0;

  self.imei = '';
  self.sim_iccid = '';
  self.mac_address = '';

  // Function to format float with 2 decimals
  function format(val) {
    return parseFloat(val).toFixed(2);
  }

  self.onDataUpdated = function () {
    self.ctx.data.forEach(dp => {
      const key = dp.dataKey.name;
      const last = dp.data[dp.data.length - 1];
      if (!last) return;

      const val = last[1];

      switch (key) {
        case 'cpu_usage':
          self.cpu_usage = format(val);
          break;
        case 'ram_usage':
          self.ram_usage = format(val);
          break;
        case 'flash_usage':
          self.flash_usage = format(val);
          break;
        case 'device_temperature':
          self.device_temperature = format(val);
          break;
        case 'imei':
          self.imei = val;
          break;
        case 'sim_iccid':
          self.sim_iccid = val;
          break;
        case 'mac_address':
          self.mac_address = val;
          break;
      }
    });
  };
};

